import{_ as e,c as d,o,a7 as a}from"./chunks/framework.D0mml042.js";const p=JSON.parse('{"title":"Beacon Config File Reference","description":"","frontmatter":{},"headers":[],"relativePath":"reference/beacon-config-reference.md","filePath":"reference/beacon-config-reference.md"}'),r={name:"reference/beacon-config-reference.md"};function c(n,t,i,l,h,s){return o(),d("div",null,[...t[0]||(t[0]=[a('<div style="display:none;" hidden="true" aria-hidden="true">Are you an LLM? You can read better optimized documentation at /virga/reference/beacon-config-reference.md for this page in Markdown format</div><h1 id="beacon-config-file-reference" tabindex="-1">Beacon Config File Reference <a class="header-anchor" href="#beacon-config-file-reference" aria-label="Permalink to &quot;Beacon Config File Reference&quot;">​</a></h1><p>This document provides a complete reference for all options available in the beacon configuration YAML file. You can use <code>configs/beacon.yaml</code> as a template.</p><h2 id="root-level" tabindex="-1">Root Level <a class="header-anchor" href="#root-level" aria-label="Permalink to &quot;Root Level&quot;">​</a></h2><ul><li><code>beacon</code> (object, required): Contains all beacon-related configuration.</li><li><code>implant</code> (object, optional): Configures the implant&#39;s internal logging.</li><li><code>llama</code> (object, optional): Configures the AI features.</li><li><code>output</code> (object, required): Defines the output file path.</li><li><code>advanced</code> (object, optional): Advanced compilation options.</li></ul><hr><h2 id="beacon" tabindex="-1"><code>beacon</code> <a class="header-anchor" href="#beacon" aria-label="Permalink to &quot;`beacon`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>c2</code></td><td>object</td><td>(Required) C2 server connection settings.</td></tr><tr><td><code>behavior</code></td><td>object</td><td>(Required) Beacon operational behavior.</td></tr><tr><td><code>target</code></td><td>object</td><td>(Required) Target platform definition.</td></tr></tbody></table><h3 id="beacon-c2" tabindex="-1"><code>beacon.c2</code> <a class="header-anchor" href="#beacon-c2" aria-label="Permalink to &quot;`beacon.c2`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>host</code></td><td>string</td><td><code>127.0.0.1</code></td><td>The IP address or hostname of the C2 server.</td></tr><tr><td><code>port</code></td><td>integer</td><td><code>8080</code></td><td>The port number of the C2 listener.</td></tr><tr><td><code>protocol</code></td><td>string</td><td><code>http</code></td><td>The communication protocol (<code>http</code> or <code>https</code>).</td></tr><tr><td><code>uri_path</code></td><td>string</td><td><code>api/updates</code></td><td>The URI path for the beacon to check in to.</td></tr></tbody></table><h3 id="beacon-behavior" tabindex="-1"><code>beacon.behavior</code> <a class="header-anchor" href="#beacon-behavior" aria-label="Permalink to &quot;`beacon.behavior`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>sleep_time</code></td><td>integer</td><td><code>60</code></td><td>The base sleep time in seconds between check-ins.</td></tr><tr><td><code>jitter</code></td><td>integer</td><td><code>20</code></td><td>The percentage of jitter to apply to the sleep time (0-100).</td></tr><tr><td><code>user_agent</code></td><td>string</td><td>(Browser-like)</td><td>The User-Agent string to use for HTTP/S requests.</td></tr></tbody></table><h3 id="beacon-target" tabindex="-1"><code>beacon.target</code> <a class="header-anchor" href="#beacon-target" aria-label="Permalink to &quot;`beacon.target`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>os</code></td><td>string</td><td><code>windows</code></td><td>The target operating system (<code>windows</code>, <code>linux</code>, <code>darwin</code>).</td></tr><tr><td><code>arch</code></td><td>string</td><td><code>amd64</code></td><td>The target architecture (<code>amd64</code>, <code>arm64</code>).</td></tr><tr><td><code>format</code></td><td>string</td><td><code>exe</code></td><td>The output file format (<code>exe</code>, <code>dll</code>, <code>elf</code>, etc.).</td></tr></tbody></table><h3 id="beacon-shell" tabindex="-1"><code>beacon.shell</code> <a class="header-anchor" href="#beacon-shell" aria-label="Permalink to &quot;`beacon.shell`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>powershell.amsi_bypass</code></td><td>string</td><td>Built-in obfuscated AMSI bypass</td><td>Optional override injected before embedded PowerShell payloads are executed.</td></tr></tbody></table><h3 id="beacon-payloads" tabindex="-1"><code>beacon.payloads</code> <a class="header-anchor" href="#beacon-payloads" aria-label="Permalink to &quot;`beacon.payloads`&quot;">​</a></h3><p>Bundled payloads let you ship scripts/tools with the beacon binary so you can execute them later using the <code>shell</code> command without touching the network.</p><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>name</code></td><td>string</td><td>Operator-facing identifier used with <code>shell @name ...</code>.</td></tr><tr><td><code>source</code></td><td>string</td><td>Local path or HTTPS URL to pull into the beacon at build time.</td></tr><tr><td><code>type</code></td><td>string</td><td>Execution runtime (currently only <code>powershell</code> is supported).</td></tr></tbody></table><blockquote><p><strong>Usage tip:</strong> Once a payload named <code>powerview</code> is defined you can execute it via <code>shell&gt; @powerview Get-NetUser</code> and virga will stream the embedded script plus your command into PowerShell with the AMSI bypass applied automatically.</p></blockquote><hr><h2 id="implant" tabindex="-1"><code>implant</code> <a class="header-anchor" href="#implant" aria-label="Permalink to &quot;`implant`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>log_enabled</code></td><td>boolean</td><td><code>false</code></td><td>Enables detailed logging within the beacon itself.</td></tr><tr><td><code>log_file_path</code></td><td>string</td><td><code>implant.log</code></td><td>The path to save the log file to on the target.</td></tr><tr><td><code>log_level</code></td><td>string</td><td><code>info</code></td><td>The logging level (<code>debug</code>, <code>info</code>, <code>warn</code>, <code>error</code>).</td></tr></tbody></table><hr><h2 id="llama" tabindex="-1"><code>llama</code> <a class="header-anchor" href="#llama" aria-label="Permalink to &quot;`llama`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>enabled</code></td><td>boolean</td><td>(Required) Enables or disables all AI features.</td></tr><tr><td><code>log_enabled</code></td><td>boolean</td><td>Enables detailed logging for the LLM engine.</td></tr><tr><td><code>model</code></td><td>object</td><td>Configures the AI model&#39;s inference parameters.</td></tr><tr><td><code>prompt</code></td><td>object</td><td>Defines the initial instruction set for the model.</td></tr><tr><td><code>autonomous</code></td><td>object</td><td>Configures the autonomous operation loop.</td></tr><tr><td><code>task_prompts</code></td><td>object</td><td>A map of custom prompts for specific tasks.</td></tr></tbody></table><h3 id="llama-model" tabindex="-1"><code>llama.model</code> <a class="header-anchor" href="#llama-model" aria-label="Permalink to &quot;`llama.model`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>context</code></td><td>integer</td><td><code>8192</code></td><td>The maximum token context size for the model.</td></tr><tr><td><code>gpu_layers</code></td><td>integer</td><td><code>0</code></td><td>Number of model layers to offload to the GPU.</td></tr><tr><td><code>threads</code></td><td>integer</td><td><code>4</code></td><td>Number of CPU threads to use for inference.</td></tr><tr><td><code>temperature</code></td><td>float</td><td><code>0.7</code></td><td>Controls the creativity of the model (0.0-1.0).</td></tr><tr><td><code>top_k</code></td><td>integer</td><td><code>40</code></td><td>Vocabulary sampling parameter.</td></tr><tr><td><code>top_p</code></td><td>float</td><td><code>0.95</code></td><td>Nucleus sampling parameter.</td></tr><tr><td><code>max_tokens</code></td><td>integer</td><td><code>2048</code></td><td>Maximum number of tokens to generate in a response.</td></tr></tbody></table><h3 id="llama-prompt" tabindex="-1"><code>llama.prompt</code> <a class="header-anchor" href="#llama-prompt" aria-label="Permalink to &quot;`llama.prompt`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>preset</code></td><td>string</td><td><code>enhanced</code></td><td>The initial system prompt preset (<code>default</code>, <code>enhanced</code>, <code>stealth</code>, <code>aggressive</code>).</td></tr></tbody></table><h3 id="llama-autonomous" tabindex="-1"><code>llama.autonomous</code> <a class="header-anchor" href="#llama-autonomous" aria-label="Permalink to &quot;`llama.autonomous`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>enabled</code></td><td>boolean</td><td>Enables the autonomous execution loop.</td></tr><tr><td><code>initial_tasks</code></td><td>array</td><td>A list of tasks for the AI to perform upon startup.</td></tr><tr><td><code>max_iterations</code></td><td>integer</td><td>The maximum number of command-execution loops for a single task.</td></tr><tr><td><code>timeout_minutes</code></td><td>integer</td><td>The timeout in minutes for the entire autonomous operation.</td></tr><tr><td><code>report_interval</code></td><td>integer</td><td>The interval in seconds for reporting progress.</td></tr></tbody></table><hr><h2 id="output" tabindex="-1"><code>output</code> <a class="header-anchor" href="#output" aria-label="Permalink to &quot;`output`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>path</code></td><td>string</td><td><code>dist/beacon.exe</code></td><td>The path to save the generated beacon file.</td></tr></tbody></table><hr><h2 id="advanced" tabindex="-1"><code>advanced</code> <a class="header-anchor" href="#advanced" aria-label="Permalink to &quot;`advanced`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>strip_symbols</code></td><td>boolean</td><td><code>true</code></td><td>Strips debugging symbols from the compiled binary.</td></tr><tr><td><code>compress</code></td><td>boolean</td><td><code>false</code></td><td>Compresses the final binary (e.g., with UPX). (Not yet implemented)</td></tr><tr><td><code>anti_debug</code></td><td>boolean</td><td><code>false</code></td><td>Includes anti-debugging techniques. (Not yet implemented)</td></tr></tbody></table>',38)])])}const u=e(r,[["render",c]]);export{p as __pageData,u as default};
